const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

/*
 * README screenshots are the one piece of the docs that cannot be regenerated by a build, so
 * they drift silently: the 0.5.0 archived-only chip shipped while palette.png still showed the
 * previous UI. This check makes the drift visible:
 *
 *   - structure (always fails): every entry in screenshots.json exists, is a PNG of a sane
 *     size, is embedded in README.md and README.zh.md, and has a screenshots.meta.json entry
 *     whose sha256 matches the bytes on disk (so a replaced image cannot skip the metadata);
 *   - freshness (fails unless acknowledged): each image records the release whose UI it shows.
 *     When that falls behind package.json the image must be re-captured, or the path must be
 *     listed in acknowledgedStale with a written reason, which keeps the debt reviewable in the
 *     repository instead of only in someone's head.
 */

const root = path.resolve(__dirname, '..');
const failures = [];

function fail(message) {
  failures.push(message);
  console.error('FAIL ' + message);
}

function warn(message) {
  console.warn('WARN ' + message);
}

function readJson(relative) {
  const target = path.join(root, relative);
  if (!fs.existsSync(target)) {
    fail('missing file: ' + relative);
    return null;
  }
  try {
    return JSON.parse(fs.readFileSync(target, 'utf8'));
  } catch (error) {
    fail('invalid JSON: ' + relative + ' (' + error.message + ')');
    return null;
  }
}

const pkg = readJson('package.json') || {};
const list = readJson('screenshots.json');
const meta = readJson('screenshots.meta.json');
const changelog = fs.existsSync(path.join(root, 'CHANGELOG.md')) ? fs.readFileSync(path.join(root, 'CHANGELOG.md'), 'utf8') : '';
const released = new Set(Array.from(changelog.matchAll(/^##\s*\[(\d+\.\d+\.\d+)\]/gm), (match) => match[1]));
const readmes = {};
for (const file of ['README.md', 'README.zh.md']) {
  const target = path.join(root, file);
  if (fs.existsSync(target)) readmes[file] = fs.readFileSync(target, 'utf8');
  else fail('missing file: ' + file);
}

if (!Array.isArray(list)) {
  fail('screenshots.json must stay a plain array of image paths (the storefront reads it)');
}
const images = list === null || !Array.isArray(list) ? [] : list;
const entries = meta && Array.isArray(meta.images) ? meta.images : [];
const acknowledged = meta && Array.isArray(meta.acknowledgedStale) ? meta.acknowledgedStale : [];

for (const relative of images) {
  if (typeof relative !== 'string' || !relative.startsWith('docs/screenshots/')) {
    fail('screenshots.json: "' + String(relative) + '" must be a docs/screenshots/*.png path');
    continue;
  }
  const target = path.join(root, relative);
  if (!fs.existsSync(target)) {
    fail('missing screenshot: ' + relative);
    continue;
  }
  const bytes = fs.readFileSync(target);
  if (bytes.length < 8 || bytes.readUInt32BE(0) !== 0x89504e47) fail('not a PNG file: ' + relative);
  if (bytes.length < 5 * 1024) fail('suspiciously small screenshot (did the capture fail?): ' + relative);

  for (const [file, text] of Object.entries(readmes)) {
    if (!text.includes('](' + relative + ')')) fail(file + ' does not embed ' + relative);
  }

  const entry = entries.find((candidate) => candidate && candidate.path === relative);
  if (!entry) {
    fail('screenshots.meta.json has no entry for ' + relative);
    continue;
  }
  const sha256 = crypto.createHash('sha256').update(bytes).digest('hex');
  if (entry.sha256 !== sha256) {
    fail('screenshots.meta.json sha256 for ' + relative + ' does not match the file — the image was replaced without updating the metadata');
  }
  if (!entry.showsVersion) {
    fail('screenshots.meta.json entry for ' + relative + ' needs showsVersion');
  } else if (!released.has(entry.showsVersion)) {
    fail('screenshots.meta.json: ' + relative + ' says showsVersion "' + entry.showsVersion + '", which is not a released version in CHANGELOG.md');
  } else if (entry.showsVersion !== pkg.version) {
    const record = acknowledged.find((candidate) => candidate && candidate.path === relative);
    if (record) warn(relative + ' shows ' + entry.showsVersion + ' while the package is ' + pkg.version + ' — acknowledged: ' + record.reason);
    else fail(relative + ' shows ' + entry.showsVersion + ' but the package is ' + pkg.version + ' — re-capture it (docs/screenshots.md) or record an acknowledgedStale reason');
  }
}

for (const entry of entries) {
  if (entry && entry.path && !images.includes(entry.path)) {
    fail('screenshots.meta.json lists ' + entry.path + ', which is not in screenshots.json');
  }
}

for (const record of acknowledged) {
  if (!record || !images.includes(record.path)) {
    fail('acknowledgedStale names an unknown image: ' + String(record && record.path));
  } else if (!record.reason || String(record.reason).trim().length < 10) {
    fail('acknowledgedStale for ' + record.path + ' needs a reason (at least a sentence)');
  }
}

if (failures.length > 0) {
  console.error('\n' + failures.length + ' screenshot check(s) failed');
  process.exitCode = 1;
} else {
  console.log(
    'screenshot checks passed (' + images.length + ' images' + (acknowledged.length ? ', ' + acknowledged.length + ' acknowledged stale' : '') + ')'
  );
}
